ALTER TABLE public.incidents ADD COLUMN IF NOT EXISTS workflow_status text NOT NULL DEFAULT 'open', ADD COLUMN IF NOT EXISTS priority text NOT NULL DEFAULT 'attention', ADD COLUMN IF NOT EXISTS request_id uuid, ADD COLUMN IF NOT EXISTS vehicle_id uuid REFERENCES public.vehicles(id), ADD COLUMN IF NOT EXISTS trip_stage text, ADD COLUMN IF NOT EXISTS latitude double precision, ADD COLUMN IF NOT EXISTS longitude double precision, ADD COLUMN IF NOT EXISTS location_captured_at timestamptz, ADD COLUMN IF NOT EXISTS driver_eta timestamptz, ADD COLUMN IF NOT EXISTS affects_deadline boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS closed_at timestamptz, ADD COLUMN IF NOT EXISTS closed_by uuid REFERENCES public.profiles(id);
UPDATE public.incidents SET workflow_status=CASE WHEN resolved_at IS NOT NULL THEN 'resolved' WHEN acknowledged_at IS NOT NULL THEN 'analysis' ELSE 'open' END,priority=CASE WHEN severity='high' THEN 'high' WHEN severity='low' THEN 'informative' ELSE 'attention' END;
ALTER TABLE public.incidents ADD CONSTRAINT incidents_workflow_status_valid CHECK(workflow_status IN ('open','received','analysis','awaiting_driver','handling','resolved','closed')), ADD CONSTRAINT incidents_priority_valid CHECK(priority IN ('informative','attention','high','critical'));
CREATE UNIQUE INDEX incidents_request_unique ON public.incidents(reported_by,request_id) WHERE request_id IS NOT NULL;
CREATE INDEX incidents_workflow_idx ON public.incidents(workflow_status,priority,created_at);
CREATE TABLE public.incident_updates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES public.incidents(id),actor_id uuid NOT NULL REFERENCES public.profiles(id),actor_name text NOT NULL,action text NOT NULL,message text,internal boolean NOT NULL DEFAULT false,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.incident_updates TO authenticated; GRANT ALL ON public.incident_updates TO service_role;
ALTER TABLE public.incident_updates ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.incident_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES public.incidents(id),file_path text NOT NULL UNIQUE,label text NOT NULL,mime_type text NOT NULL,size_bytes bigint NOT NULL,uploaded_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.incident_files TO authenticated; GRANT ALL ON public.incident_files TO service_role;
ALTER TABLE public.incident_files ENABLE ROW LEVEL SECURITY;
CREATE INDEX incident_updates_incident_idx ON public.incident_updates(incident_id,created_at);
CREATE INDEX incident_files_incident_idx ON public.incident_files(incident_id);
CREATE OR REPLACE FUNCTION public.can_access_incident(_incident uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND EXISTS(SELECT 1 FROM public.incidents WHERE id=_incident AND (reported_by=_user OR public.can_manage_operation_board(_user))); $$;
REVOKE ALL ON FUNCTION public.can_access_incident(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_access_incident(uuid,uuid) TO authenticated,service_role;
CREATE POLICY incident_updates_read ON public.incident_updates FOR SELECT TO authenticated USING(public.can_access_incident(incident_id,auth.uid()) AND (NOT internal OR public.can_manage_operation_board(auth.uid())));
CREATE POLICY incident_files_read ON public.incident_files FOR SELECT TO authenticated USING(public.can_access_incident(incident_id,auth.uid()));
CREATE POLICY incidents_private_read ON public.incidents AS RESTRICTIVE FOR SELECT TO authenticated USING(reported_by=auth.uid() OR public.can_manage_operation_board(auth.uid()));
CREATE POLICY incidents_managers_read ON public.incidents FOR SELECT TO authenticated USING(public.can_manage_operation_board(auth.uid()));
CREATE POLICY incidents_rpc_insert_only ON public.incidents AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.can_manage_operation_board(auth.uid()));
CREATE POLICY incidents_rpc_update_only ON public.incidents AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.can_manage_operation_board(auth.uid())) WITH CHECK(public.can_manage_operation_board(auth.uid()));
CREATE POLICY incident_objects_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='incident-files' AND public.can_access_incident((storage.foldername(name))[1]::uuid,auth.uid()));
CREATE POLICY incident_objects_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='incident-files' AND EXISTS(SELECT 1 FROM public.incidents WHERE id=(storage.foldername(name))[1]::uuid AND reported_by=auth.uid() AND closed_at IS NULL));
CREATE POLICY incident_objects_private_read ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'incident-files' OR public.can_access_incident((storage.foldername(name))[1]::uuid,auth.uid()));
CREATE POLICY incident_objects_private_upload ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'incident-files' OR EXISTS(SELECT 1 FROM public.incidents WHERE id=(storage.foldername(name))[1]::uuid AND reported_by=auth.uid() AND closed_at IS NULL));
CREATE POLICY incident_objects_immutable ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(bucket_id<>'incident-files') WITH CHECK(bucket_id<>'incident-files');
CREATE POLICY incident_objects_no_delete ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'incident-files');
CREATE POLICY incident_events_private_read ON public.order_events AS RESTRICTIVE FOR SELECT TO authenticated USING(event_type NOT LIKE 'driver_incident_%' AND event_type NOT LIKE 'operational_alert_%' OR public.can_manage_operation_board(auth.uid()));
CREATE OR REPLACE FUNCTION public.sync_incident_legacy_workflow() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.resolved_at IS NOT NULL AND NEW.workflow_status NOT IN ('resolved','closed') THEN NEW.workflow_status:='resolved'; ELSIF NEW.acknowledged_at IS NOT NULL AND NEW.workflow_status='open' THEN NEW.workflow_status:='received'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sync_incident_legacy_workflow BEFORE UPDATE ON public.incidents FOR EACH ROW EXECUTE FUNCTION public.sync_incident_legacy_workflow();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['incident_updates','incident_files'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',t); END IF; END LOOP; END $$;